-- MDM practice raw staging load for PostgreSQL
-- Datos ficticios. Extraídos en crudo: no aplicar limpieza al cargar.
BEGIN;
DROP TABLE IF EXISTS crm_customers;
CREATE TABLE crm_customers (
  contact_id TEXT,
  first_name TEXT,
  last_name TEXT,
  email TEXT,
  phone TEXT,
  street TEXT,
  city TEXT,
  state TEXT,
  postal_code TEXT,
  company TEXT,
  created_at TEXT,
  updated_at TEXT,
  source_system TEXT
);
DROP TABLE IF EXISTS erp_customers;
CREATE TABLE erp_customers (
  customer_no TEXT,
  rfc TEXT,
  razon_social TEXT,
  contact_name TEXT,
  email TEXT,
  telefono TEXT,
  direccion TEXT,
  ciudad TEXT,
  estado TEXT,
  cp TEXT,
  credit_limit TEXT,
  currency TEXT,
  status TEXT,
  last_invoice_date TEXT
);
DROP TABLE IF EXISTS marketing_leads;
CREATE TABLE marketing_leads (
  lead_id TEXT,
  full_name TEXT,
  email TEXT,
  phone TEXT,
  signup_date TEXT,
  utm_source TEXT,
  country TEXT
);
DROP TABLE IF EXISTS weekly_issues;
CREATE TABLE weekly_issues (
  week TEXT,
  source TEXT,
  issue_type TEXT,
  issue_count TEXT
);
COMMIT;

-- Conteos de verificación
SELECT 'crm_customers' AS tabla, COUNT(*) AS filas FROM crm_customers
UNION ALL
SELECT 'erp_customers' AS tabla, COUNT(*) AS filas FROM erp_customers
UNION ALL
SELECT 'marketing_leads' AS tabla, COUNT(*) AS filas FROM marketing_leads
UNION ALL
SELECT 'weekly_issues' AS tabla, COUNT(*) AS filas FROM weekly_issues;
